-- ============================================================================
-- Migration: 031_profile_photos_storage_policies.sql
-- Purpose : Secure private profile photo storage
-- Bucket  : profile-photos
-- ============================================================================

-- 1. SELECT
-- Active authenticated users can read photos.
-- The bucket remains private; access is through authenticated requests
-- and signed URLs generated by the application.

DROP POLICY IF EXISTS "profile_photos_select_authenticated"
ON storage.objects;

CREATE POLICY "profile_photos_select_authenticated"
ON storage.objects
FOR SELECT
TO authenticated
USING (
    bucket_id = 'profile-photos'
    AND EXISTS (
        SELECT 1
        FROM public.profiles p
        WHERE p.id = auth.uid()
          AND p.is_active = true
    )
);

-- 2. INSERT
-- Admin/Super Admin can upload employee photos.
-- Other users can upload only their own linked employee photo.
-- Users without an employee link can upload their own profile photo.

DROP POLICY IF EXISTS "profile_photos_insert_authorized"
ON storage.objects;

CREATE POLICY "profile_photos_insert_authorized"
ON storage.objects
FOR INSERT
TO authenticated
WITH CHECK (
    bucket_id = 'profile-photos'
    AND (
        (
            array_length(storage.foldername(name), 1) = 2
            AND (storage.foldername(name))[1] = 'employees'
            AND (storage.foldername(name))[2] ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            AND storage.filename(name) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\.webp$'
            AND EXISTS (
                SELECT 1
                FROM public.profiles p
                WHERE p.id = auth.uid()
                  AND p.is_active = true
            )
            AND (
                private.is_admin(auth.uid())
                OR (
                    private.get_employee_id(auth.uid()) IS NOT NULL
                    AND (storage.foldername(name))[2] =
                        private.get_employee_id(auth.uid())::text
                )
            )
        )
        OR
        (
            array_length(storage.foldername(name), 1) = 2
            AND (storage.foldername(name))[1] = 'profiles'
            AND (storage.foldername(name))[2] ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            AND storage.filename(name) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\.webp$'
            AND (storage.foldername(name))[2] = auth.uid()::text
            AND private.get_employee_id(auth.uid()) IS NULL
            AND EXISTS (
                SELECT 1
                FROM public.profiles p
                WHERE p.id = auth.uid()
                  AND p.is_active = true
            )
        )
    )
);

-- 3. DELETE
-- Admin/Super Admin can delete employee photo objects.
-- Other users can delete only their own employee photo objects.
-- Users without an employee link can delete their own profile photo objects.

DROP POLICY IF EXISTS "profile_photos_delete_authorized"
ON storage.objects;

CREATE POLICY "profile_photos_delete_authorized"
ON storage.objects
FOR DELETE
TO authenticated
USING (
    bucket_id = 'profile-photos'
    AND (
        (
            array_length(storage.foldername(name), 1) = 2
            AND (storage.foldername(name))[1] = 'employees'
            AND (storage.foldername(name))[2] ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            AND storage.filename(name) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\.webp$'
            AND EXISTS (
                SELECT 1
                FROM public.profiles p
                WHERE p.id = auth.uid()
                  AND p.is_active = true
            )
            AND (
                private.is_admin(auth.uid())
                OR (
                    private.get_employee_id(auth.uid()) IS NOT NULL
                    AND (storage.foldername(name))[2] =
                        private.get_employee_id(auth.uid())::text
                )
            )
        )
        OR
        (
            array_length(storage.foldername(name), 1) = 2
            AND (storage.foldername(name))[1] = 'profiles'
            AND (storage.foldername(name))[2] ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            AND storage.filename(name) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\.webp$'
            AND (storage.foldername(name))[2] = auth.uid()::text
            AND private.get_employee_id(auth.uid()) IS NULL
            AND EXISTS (
                SELECT 1
                FROM public.profiles p
                WHERE p.id = auth.uid()
                  AND p.is_active = true
            )
        )
    )
);